1: import fs from "node:fs";
2: import os from "node:os";
3: import path from "node:path";
4: import { fileURLToPath, pathToFileURL } from "node:url";
5: import { spawnSync } from "node:child_process";
6: import ts from "typescript";
7: import { annotate } from "./annotate.mjs";
8: import { compareEmission, sha256 } from "./emission.mjs";
9: 
10: const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
11: const maximumBytes = 1024 * 1024;
12: function snapshot(target) {
13:   try {
14:     const stat = fs.lstatSync(target);
15:     if (!stat.isFile() || stat.isSymbolicLink() || stat.size > maximumBytes)
16:       throw new Error("Generation target must be a regular file of at most 1 MiB");
17:     return { hash: sha256(fs.readFileSync(target)), mode: stat.mode & 0o777 };
18:   } catch (error) {
19:     if (error.code === "ENOENT") return null;
20:     throw error;
21:   }
22: }
23: 
24: // Both modes verify the same fresh output; neither touches the target during verification.
25: function verifiedGeneration() {
26:   const lock = JSON.parse(fs.readFileSync(path.join(root, "package-lock.json"), "utf8"));
27:   if (lock.packages?.["node_modules/typescript"]?.version !== ts.version)
28:     throw new Error("Installed TypeScript differs from package-lock.json");
29:   const scratch = fs.mkdtempSync(path.join(os.tmpdir(), "ollama-gotypes-"));
30:   try {
31:     const ui = path.dirname(root);
32:     const env = { ...process.env, TMPDIR: scratch, TMP: scratch, TEMP: scratch };
33:     const upstreamRuns = [];
34:     const run = args => {
35:       const result = spawnSync("go", args, { cwd: ui, env, encoding: "utf8", timeout: 120000, maxBuffer: 4 * maximumBytes });
36:       if (result.error || result.status !== 0)
37:         throw new Error(`Go generation failed (exit ${result.status}): ${result.error?.message ?? ""}\n${result.stdout ?? ""}${result.stderr ?? ""}`);
38:       upstreamRuns.push({ argv: ["go", ...args], exit_code: result.status, stdout: result.stdout, stderr: result.stderr });
39:       if (result.stderr) process.stderr.write(result.stderr);
40:       return result.stdout;
41:     };
42:     const module = JSON.parse(run(["list", "-m", "-json", "github.com/tkrajina/typescriptify-golang-structs"]));
43:     if (module.Version !== "v0.2.0" || module.Replace)
44:       throw new Error("Unsupported typescriptify version or module replacement");
45:     const rawPath = path.join(scratch, "gotypes.raw.ts");
46:     run(["run", "github.com/tkrajina/typescriptify-golang-structs/tscriptify",
47:       "-package=github.com/ollama/ollama/app/ui/responses", `-target=${rawPath}`, "responses/types.go"]);
48:     if (fs.statSync(rawPath).size > maximumBytes) throw new Error("Generated source exceeds 1 MiB");
49:     const raw = fs.readFileSync(rawPath, "utf8");
50:     const result = annotate(raw);
51:     if (Buffer.byteLength(result.text) > maximumBytes) throw new Error("Annotated source exceeds 1 MiB");
52:     const emission = compareEmission(raw, result.text, root);
53:     return { ...result, raw_sha256: sha256(raw), emission, generator_version: module.Version, upstream_runs: upstreamRuns };
54:   } finally {
55:     // Only the private directory just created by this invocation is disposable.
56:     fs.rmSync(scratch, { recursive: true, force: true });
57:   }
58: }
59: 
60: export function generate({ check = false, output = path.join(root, "codegen/gotypes.gen.ts") } = {}) {
61:   const target = path.resolve(output), before = snapshot(target);
62:   const verified = verifiedGeneration();
63:   const after = snapshot(target);
64:   if (JSON.stringify(before) !== JSON.stringify(after)) throw new Error("Generation target changed concurrently");
65:   if (check) {
66:     if (after?.hash !== sha256(verified.text)) throw new Error("Generated types are stale; run npm run generate:types");
67:   } else {
68:     const stage = fs.mkdtempSync(path.join(path.dirname(target), ".gotypes-"));
69:     try {
70:       const temporary = path.join(stage, "output.ts");
71:       fs.writeFileSync(temporary, verified.text, { flag: "wx", mode: before?.mode ?? 0o644 });
72:       fs.renameSync(temporary, target);
73:     } finally {
74:       fs.rmSync(stage, { recursive: true, force: true });
75:     }
76:   }
77:   const { text, ...receipt } = verified;
78:   return { ...receipt, output: target, output_sha256: sha256(text), mode: check ? "check" : "write" };
79: }
