81: function main(args) {
82:   let check = false, output;
83:   for (let i = 0; i < args.length; i++) {
84:     if (args[i] === "--check" && !check) check = true;
85:     else if (args[i] === "--output" && output === undefined && args[i + 1] && !args[i + 1].startsWith("--")) output = args[++i];
86:     else throw new Error("Usage: node codegen/generate.mjs [--check] [--output FILE]");
87:   }
88:   console.log(JSON.stringify(generate({ check, output }), null, 2));
89: }
90: if (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href) {
91:   try { main(process.argv.slice(2)); }
92:   catch (error) { console.error(error.message); process.exitCode = 1; }
